    return ('+', left[0], right[0], right[1])

# Combinator for matching a multiplication operation
function multiplication(input):
    left = number(input)
    if left is FAILURE or left[1] does not start with '*':
        return FAILURE
    right = expression(left[1][1:])
    if right is FAILURE:
        return FAILURE
    return ('*', left[0], right[0], right[1])

# Combinator for matching an arithmetic expression
function expression(input):
    result = addition(input)
    if result is not FAILURE:
        return result
